  const configuredName = language === "ar" ? settings.data?.projectNameArabic : settings.data?.projectName;
  const brandName = /\b(?:qa|sync check|delete after validation)\b/i.test(configuredName ?? "") ? "Maintainr" : configuredName || "Maintainr";
  const brandLogo = settings.data?.logoUrl || DEFAULT_MAINTAINR_LOGO;
  const primaryColor = settings.data?.primaryColor || "#0F766E";
  const Icon = meta.icon;
  const roleArabic: Record<Role, string> = { PROPERTY_MANAGER: "مدير العقار", TENANT: "المستأجر", TECHNICIAN: "الفني", FLAT_OWNER: "مالك الشقة" };
  const navItems = role === "PROPERTY_MANAGER" ? [{ label: t("Overview", "نظرة عامة"), href: meta.path, icon: LayoutDashboard }, { label: t("Analytics", "التحليلات"), href: `${meta.path}?view=analytics`, icon: ChartNoAxesCombined }, { label: t("Tickets", "البلاغات"), href: `${meta.path}?view=tickets`, icon: ClipboardList }, { label: t("Calendar", "التقويم"), href: `${meta.path}?view=calendar`, icon: CalendarDays }, { label: t("Messages", "الرسائل"), href: `${meta.path}?view=messages`, icon: MessageSquare }, { label: t("Inquiries", "الاستفسارات"), href: `${meta.path}?view=inquiries`, icon: CircleHelp }, { label: t("People", "الأشخاص"), href: `${meta.path}?view=people`, icon: Users }, { label: t("Reminders", "التذكيرات"), href: `${meta.path}?view=reminders`, icon: Clock3 }, { label: t("Profile", "الملف الشخصي"), href: "/profile", icon: UserRound }] as const : role === "TENANT" ? [{ label: t("Overview", "نظرة عامة"), href: meta.path, icon: LayoutDashboard }, { label: t("My requests", "طلباتي"), href: `${meta.path}?view=tickets`, icon: ClipboardList }, { label: t("Calendar", "التقويم"), href: `${meta.path}?view=calendar`, icon: CalendarDays }, { label: t("Messages", "الرسائل"), href: `${meta.path}?view=messages`, icon: MessageSquare }, { label: t("Inquiries", "الاستفسارات"), href: `${meta.path}?view=inquiries`, icon: CircleHelp }, { label: t("Profile", "الملف الشخصي"), href: "/profile", icon: UserRound }] as const : role === "TECHNICIAN" ? [{ label: t("Today", "اليوم"), href: meta.path, icon: LayoutDashboard }, { label: t("Assigned jobs", "المهام المسندة"), href: `${meta.path}?view=tickets`, icon: ClipboardList }, { label: t("Calendar", "التقويم"), href: `${meta.path}?view=calendar`, icon: CalendarDays }, { label: t("Messages", "الرسائل"), href: `${meta.path}?view=messages`, icon: MessageSquare }, { label: t("Profile", "الملف الشخصي"), href: "/profile", icon: UserRound }] as const : [{ label: t("Overview", "نظرة عامة"), href: meta.path, icon: LayoutDashboard }, { label: t("Reports", "التقارير"), href: `${meta.path}?view=reports`, icon: FileText }, { label: t("Calendar", "التقويم"), href: `${meta.path}?view=calendar`, icon: CalendarDays }, { label: t("Messages", "الرسائل"), href: `${meta.path}?view=messages`, icon: MessageSquare }, { label: t("Inquiries", "الاستفسارات"), href: `${meta.path}?view=inquiries`, icon: CircleHelp }, { label: t("Profile", "الملف الشخصي"), href: "/profile", icon: UserRound }] as const;
  const initials = (user?.name || user?.email || "U").split(/[\s@]+/).filter(Boolean).slice(0, 2).map(part => part[0]).join("").toUpperCase();
