  const unreadNotifications = (utilityReminders.data ?? []).filter((reminder) => !reminder.isAcknowledged).length;

  useEffect(() => {
    document.title = brandName;
    document.documentElement.style.setProperty("--brand-primary", primaryColor);
    document.documentElement.style.setProperty("--brand-accent", settings.data?.accentColor || "#0EA5E9");
    const favicon = document.querySelector<HTMLLinkElement>('link[rel="icon"]') ?? document.head.appendChild(Object.assign(document.createElement("link"), { rel: "icon" }));
    favicon.href = brandLogo || "/favicon.svg";
  }, [brandName, brandLogo, primaryColor, settings.data?.accentColor]);

